29	//
30	// 只相加传入的同一角色物品，不同角色必须分别调用、绝不合并。求和用精确
31	// 整数完成、不回绕，因此真实总量允许超过 int 最大值；是否超限交由上限
32	// 判断另行决定。
33	func carryTotal(items []CharacterItem) *big.Int {
34		total := new(big.Int)
35		for _, it := range items {
36			total.Add(total, bigInt(it.Count))
37		}
38		return total
39	}
