42	// 合法，大于上限才拒绝。total 为精确真实总量（见 carryTotal），limit 是
43	// 已确认存在的非负上限；调用方需先区分“上限为 0”与“未设置上限”。
44	func totalExceedsLimit(total *big.Int, limit int) bool {
45		return total.Cmp(bigInt(limit)) > 0
46	}
