49	// 说明角色、完整十进制真实总量与上限的规则错误。
50	//
51	// 上限语义集中在此：limits 中没有该角色的键表示不设上限，该角色不受任何
52	// 总量约束（即使各物品数量相加超过 int 最大值也合法），不受其他角色上限
53	// 影响；键存在且值为 0 仍是真实上限，表示只能携带总量为 0 的物品，不能
54	// 当作未设置。建立/重建世界、提交物品变化与存档校验共用本判断。
55	func carryLimitError(charID string, items []CharacterItem, limits map[string]int) error {
56		limit, hasLimit := limits[charID]
57		if !hasLimit {
