5	// findCharacter 按标识查找角色，找不到时测试失败。
6	func findCharacter(t *testing.T, st State, id string) Character {
7		t.Helper()
8		for _, ch := range st.Characters {
9			if ch.ID == id {
10				return ch
11			}
12		}
13		t.Fatalf("状态中不存在角色 %q", id)
14		return Character{}
15	}
16	
17	// 同一次提交中的连续移动按给定次序逐步生效，每一步都从前一步结束后的
18	// 地点出发：地图只有 hall-yard、yard-cave 相连，hero 从 hall 出发在同一
19	// 提交中经 yard 到 cave 应当成功。成功后时间片等于提交指定的绝对值，
20	// 不因走了两步而额外增加；同次提交的合法物品增减照常生效。
21	func TestApplyMultiMoveThroughIntermediate(t *testing.T) {
22		w := baseWorld(t)
23		st, err := w.Apply(Commit{
24			Moves: []Move{
25				{Character: "hero", To: "yard"},
26				{Character: "hero", To: "cave"},
27			},
28			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 2}},
29			Time:        5,
30		})
31		if err != nil {
32			t.Fatalf("经中间地点的连续移动应成功: %v", err)
33		}
34		if st.Time != 5 {
35			t.Fatalf("时间片应等于提交的绝对值 5，得到 %d", st.Time)
36		}
37		hero := findCharacter(t, st, "hero")
38		if hero.Location != "cave" {
39			t.Fatalf("hero 应位于 cave，得到 %q", hero.Location)
40		}
41		if len(hero.Items) != 1 || hero.Items[0] != (CharacterItem{Item: "gold", Count: 3}) {
42			t.Fatalf("hero 物品应为 3 个 gold，得到 %+v", hero.Items)
43		}
44		if mage := findCharacter(t, st, "mage"); mage.Location != "yard" || len(mage.Items) != 0 {
45			t.Fatalf("mage 不应受影响，得到 %+v", mage)
46		}
47		// 世界状态与返回状态一致。
48		if got := findCharacter(t, w.Snapshot(), "hero"); got.Location != "cave" {
49			t.Fatalf("世界中的 hero 应位于 cave，得到 %q", got.Location)
50		}
51	}
52	
53	// 角色已处于非零时间片时，允许在不推进时间的情况下于当前时间片内完成
54	// 合法的连续移动，不要求每一步分别推进时间。
55	func TestApplyMultiMoveWithinCurrentTimeSlice(t *testing.T) {
56		w := baseWorld(t)
57		if _, err := w.Apply(Commit{
58			Moves: []Move{{Character: "hero", To: "yard"}},
59			Time:  4,
60		}); err != nil {
61			t.Fatalf("首次提交: %v", err)
62		}
63		st, err := w.Apply(Commit{
64			Moves: []Move{
65				{Character: "hero", To: "cave"},
66				{Character: "hero", To: "yard"},
67			},
68			Time: 4,
69		})
70		if err != nil {
71			t.Fatalf("当前时间片内的连续移动应成功: %v", err)
72		}
73		if st.Time != 4 {
74			t.Fatalf("时间片应保持 4，得到 %d", st.Time)
75		}
76		if got := findCharacter(t, st, "hero").Location; got != "yard" {
77			t.Fatalf("hero 应回到 yard，得到 %q", got)
78		}
79	}
80	
81	// 沿相同的无向道路反向移动仍然允许：同一提交中按合法路线折返至起点
82	// 应当成功，中间地点不必留在最终状态里，角色与物品的排列保持原有约定。
83	func TestApplyMultiMoveRoundTrip(t *testing.T) {
84		w := baseWorld(t)
85		before := w.Snapshot()
86		st, err := w.Apply(Commit{
87			Moves: []Move{
88				{Character: "hero", To: "yard"},
89				{Character: "hero", To: "cave"},
90				{Character: "hero", To: "yard"},
91				{Character: "hero", To: "hall"},
92			},
93			Time: 2,
94		})
95		if err != nil {
96			t.Fatalf("折返起点的连续移动应成功: %v", err)
97		}
98		if st.Time != 2 {
99			t.Fatalf("时间片应为 2，得到 %d", st.Time)
100		}
101		hero := findCharacter(t, st, "hero")
102		if hero.Location != "hall" {
103			t.Fatalf("hero 应回到 hall，得到 %q", hero.Location)
104		}
105		if len(hero.Items) != 1 || hero.Items[0] != (CharacterItem{Item: "gold", Count: 1}) {
106			t.Fatalf("hero 物品应保持不变，得到 %+v", hero.Items)
107		}
108		if mage := findCharacter(t, st, "mage"); mage.Location != "yard" || len(mage.Items) != 0 {
109			t.Fatalf("mage 不应受影响，得到 %+v", mage)
110		}
111		// 除时间片外，世界状态与提交前一致。
112		after := w.Snapshot()
113		after.Time = before.Time
114		if !statesEqual(before, after) {
115			t.Fatal("折返后除时间片外世界状态应与提交前一致")
116		}
117	}
118	
119	// 移动条目按次序逐步判定：目的地集合相同但次序非法时（第一步就没有
120	// 道路）必须失败，不能只根据起点和最终目的地判断是否允许。
121	func TestApplyMultiMoveOrderMatters(t *testing.T) {
122		w := baseWorld(t)
123		before := w.Snapshot()
124		_, err := w.Apply(Commit{
125			Moves: []Move{
126				{Character: "hero", To: "cave"},
127				{Character: "hero", To: "yard"},
128			},
129			Time: 1,
130		})
131		mustRuleError(t, err, "hero", "hall", "cave")
132		if after := w.Snapshot(); !statesEqual(before, after) {
133			t.Fatal("次序非法的提交改变了世界状态")
134		}
135	}
136	
137	// 整段路线中最后一步没有道路时整次提交失败：hall→yard→cave 合法，但
138	// cave→hall 没有连通关系，即使最终地点与起点相同也不能算成功。失败后
139	// 角色位置、物品数量和时间片都与提交前一致，不留下部分移动结果。
140	func TestApplyMultiMoveRejectedLeavesNoTrace(t *testing.T) {
141		w := baseWorld(t)
142		before := w.Snapshot()
143		_, err := w.Apply(Commit{
144			Moves: []Move{
145				{Character: "hero", To: "yard"},
146				{Character: "hero", To: "cave"},
147				{Character: "hero", To: "hall"},
148			},
149			ItemChanges: []ItemChange{{Character: "hero", Item: "gold", Delta: 1}},
150			Time:        3,
151		})
152		mustRuleError(t, err, "hero", "cave", "hall")
153		after := w.Snapshot()
154		if !statesEqual(before, after) {
155			t.Fatalf("失败提交留下了部分结果: 前 %+v, 后 %+v", before, after)
156		}
157		if after.Time != 0 {
158			t.Fatalf("时间片不应推进，得到 %d", after.Time)
159		}
160	}
161	
162	// 同次提交中路线全部合法，但物品增减使角色超过携带上限时整次失败，
163	// 前面的移动不能保留；之后仍能从提交前的位置按原规则继续操作。
164	func TestApplyMultiMoveItemOverflowRollsBack(t *testing.T) {
165		w := baseWorld(t)
166		before := w.Snapshot()
167		_, err := w.Apply(Commit{
168			Moves: []Move{
169				{Character: "hero", To: "yard"},
170				{Character: "hero", To: "cave"},
171			},
172			ItemChanges: []ItemChange{{Character: "hero", Item: "key", Delta: 6}},
173			Time:        2,
174		})
175		mustRuleError(t, err, "hero", "上限")
176		if after := w.Snapshot(); !statesEqual(before, after) {
177			t.Fatal("超上限的提交应整体回滚，但世界状态发生了变化")
178		}
179		// 仍能从提交前的位置继续操作。
180		st, err := w.Apply(Commit{
181			Moves: []Move{{Character: "hero", To: "yard"}},
