35	// 同一角色同一物品的增减与原始数量合并后判断：1 + MaxInt + MinInt = 0，
36	// 且与条目次序无关。
37	func TestApplyMergesDeltasExactly(t *testing.T) {
38		deltas := [][]ItemChange{
39			{{Character: "hero", Item: "gold", Delta: math.MaxInt}, {Character: "hero", Item: "gold", Delta: math.MinInt}},
40			{{Character: "hero", Item: "gold", Delta: math.MinInt}, {Character: "hero", Item: "gold", Delta: math.MaxInt}},
41		}
42		for _, d := range deltas {
43			w, err := NewWorld(InitialData{
44				Seed:  1,
45				Rules: noLimitRules(),
