221			Time: 9,
222		})
223		mustRuleError(t, err, "hero")
224		after := w.Snapshot()
225		if !reflect.DeepEqual(before, after) {
226			t.Fatalf("失败提交应整体撤销，之前 %+v 之后 %+v", before, after)
227		}
228	}
229	
230	// 建立世界与从完整状态继续时，携带上限同样按真实总量判断。
231	func TestBuildWorldLimitUsesTrueTotal(t *testing.T) {
232		rules := noLimitRules()
233		rules.CarryLimits = map[string]int{"hero": 5}
234		chars := []Character{
235			{ID: "hero", Location: "hall", Items: []CharacterItem{
236				{Item: "gold", Count: math.MaxInt},
237				{Item: "key", Count: math.MaxInt},
238			}},
239		}
240		if _, err := NewWorld(InitialData{Seed: 1, Rules: rules, Characters: chars}); err == nil {
241			t.Fatalf("真实总量超限应拒绝建立世界")
242		} else {
243			mustRuleError(t, err, "hero", "上限")
244		}
245		if _, err := WorldFromState(State{Seed: 1, Rules: rules, Characters: chars}); err == nil {
246			t.Fatalf("真实总量超限应拒绝从状态继续")
247		} else {
248			mustRuleError(t, err, "hero", "上限")
249		}
250		// 未设上限时同样的总量合法。
251		rules.CarryLimits = nil
252		if _, err := NewWorld(InitialData{Seed: 1, Rules: rules, Characters: chars}); err != nil {
253			t.Fatalf("无上限角色总量大应允许建立世界: %v", err)
254		}
255		if _, err := WorldFromState(State{Seed: 1, Rules: rules, Characters: chars}); err != nil {
256			t.Fatalf("无上限角色总量大应允许从状态继续: %v", err)
257		}
258	}
