260	// 升级检查按真实总量判断：来源无上限、总量超过 int 最大值，目标设置
261	// 上限时必须报告上限阻碍，并给出完整十进制真实总量。
262	func TestCheckUpgradeTrueTotalOverflow(t *testing.T) {
263		a, _ := newTestArchive(t)
264		w, err := NewWorld(InitialData{
265			Seed:  1,
266			Rules: noLimitRules(),
267			Characters: []Character{
268				{ID: "hero", Location: "hall", Items: []CharacterItem{
269					{Item: "gold", Count: math.MaxInt},
270					{Item: "key", Count: math.MaxInt},
271				}},
272			},
273		})
274		if err != nil {
275			t.Fatalf("NewWorld: %v", err)
276		}
277		info, err := a.Save("slot", w)
278		if err != nil {
279			t.Fatalf("Save: %v", err)
280		}
281	
282		target := noLimitRules()
283		target.Version = "v2"
284		target.CarryLimits = map[string]int{"hero": 10}
285		check, err := a.CheckUpgrade("slot", []string{"v1"}, target)
286		if err != nil {
287			t.Fatalf("CheckUpgrade: %v", err)
288		}
289		if check.Compatible {
290			t.Fatalf("真实总量超过目标上限应不兼容")
291		}
292		if len(check.Blockers) != 1 {
293			t.Fatalf("应只有上限阻碍，得到 %+v", check.Blockers)
294		}
295		b := check.Blockers[0]
296		if b.Character != "hero" || b.Kind != BlockerLimit || b.Limit != 10 {
297			t.Fatalf("阻碍内容不符: %+v", b)
298		}
299		if !b.TotalOverflow {
300			t.Fatalf("真实总量超出 int 范围时 TotalOverflow 应为真: %+v", b)
301		}
302		wantTotal := new(big.Int).Add(big.NewInt(math.MaxInt), big.NewInt(math.MaxInt)).String()
303		if b.TotalText != wantTotal {
304			t.Fatalf("TotalText 应为完整十进制真实总量 %s，得到 %q", wantTotal, b.TotalText)
305		}
306	
307		// 正式升级不得保存，槽当前记录与历史不变。
308		if _, err := a.Upgrade("slot", []string{"v1"}, target, info.ID); err == nil {
309			t.Fatalf("有上限阻碍时升级应被拒绝")
310		} else {
311			mustRuleError(t, err)
312		}
313		latest, err := a.Latest("slot", []string{"v1"})
314		if err != nil {
315			t.Fatalf("Latest: %v", err)
316		}
317		if latest.ID != info.ID {
318			t.Fatalf("被拒绝的升级不应改变槽当前记录")
319		}
320		history, err := a.History("slot")
321		if err != nil {
322			t.Fatalf("History: %v", err)
323		}
324		if len(history) != 1 || history[0].ID != info.ID {
325			t.Fatalf("被拒绝的升级不应改变历史: %+v", history)
326		}
327	}
