329	// 真实总量能用 int 表示时，上限阻碍沿用 Total 字段且不置 TotalOverflow。
330	func TestCheckUpgradeTotalFitsInt(t *testing.T) {
331		a, _ := newTestArchive(t)
332		w, err := NewWorld(InitialData{
333			Seed:  1,
334			Rules: noLimitRules(),
335			Characters: []Character{
336				{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 8}}},
337			},
338		})
339		if err != nil {
340			t.Fatalf("NewWorld: %v", err)
341		}
342		if _, err := a.Save("slot", w); err != nil {
343			t.Fatalf("Save: %v", err)
344		}
345		target := noLimitRules()
346		target.Version = "v2"
347		target.CarryLimits = map[string]int{"hero": 5}
348		check, err := a.CheckUpgrade("slot", []string{"v1"}, target)
