358	// writeIllegalLimitRecord 直接写入一条“校验和正确但违反携带上限”的记录
359	// （模拟旧版本回绕缺陷留下的存档），并把槽指针指向它。
360	func writeIllegalLimitRecord(t *testing.T, a *Archive, dir, slot string) (badID, goodID RecordID) {
361		t.Helper()
362		w, err := NewWorld(InitialData{
363			Seed:  1,
364			Rules: noLimitRules(),
365			Characters: []Character{
366				{ID: "hero", Location: "hall", Items: []CharacterItem{{Item: "gold", Count: 1}}},
367			},
368		})
369		if err != nil {
370			t.Fatalf("NewWorld: %v", err)
371		}
372		good, err := a.Save(slot, w)
373		if err != nil {
374			t.Fatalf("Save: %v", err)
375		}
376		// 构造违反携带上限的状态：上限 5，真实总量 1+6=7。
377		st := w.Snapshot()
378		st.Rules.CarryLimits = map[string]int{"hero": 5}
379		st.Characters[0].Items = append(st.Characters[0].Items, CharacterItem{Item: "key", Count: 6})
380		env := &envelope{
381			Format: archiveFormatVersion,
382			ID:     RecordID("r" + strings.Repeat("ab", 16)),
383			Parent: good.ID,
384			State:  st,
385		}
386		env.Checksum = computeChecksum(env)
387		if err := writeRecord(dir, env); err != nil {
388			t.Fatalf("writeRecord: %v", err)
389		}
390		if err := a.persistSlotPointerLocked(slot, slotPointer{
391			Latest:  env.ID,
392			History: []RecordID{env.ID, good.ID},
393		}); err != nil {
394			t.Fatalf("persistSlotPointerLocked: %v", err)
395		}
396		return env.ID, good.ID
397	}
