537			t.Fatalf("没有可用记录应返回 ErrUnrecoverable，得到 %v", err)
538		}
539		if _, err := a.PreviewRecovery("slot", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
540			t.Fatalf("没有可用记录时预览应返回 ErrUnrecoverable，得到 %v", err)
541		}
542	}
