// 任一角色失败时，整次提交的移动、物品变化与时间推进全部撤销。
func TestApplyFailureRollsBackEverything(t *testing.T) {
	rules := noLimitRules()
	rules.CarryLimits = map[string]int{"hero": math.MaxInt}
	w, err := NewWorld(InitialData{
		Seed:  1,
		Rules: rules,
